import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { BookService } from '@services/BookService';
import { LoanService } from '@services/LoanService';

@Component({
  selector: 'app-books',
  templateUrl: './books.component.html',
  styleUrls: ['./books.component.css']
})
export class BooksComponent implements OnInit {
  books: any[] = [];
  filteredBooks: any[] = [];
  searchQuery: string = '';
  loading: boolean = true;
  isLoaning: boolean = false;
  loaningBookId: string = '';
  errorMessage: string = '';
  successMessage: string = '';

  constructor(
    private bookService: BookService,
    private loanService: LoanService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadBooks();
  }

  loadBooks(): void {
    this.bookService.getAllBooks().subscribe(
      (response: any) => {
        this.books = response.books || response;
        this.filteredBooks = this.books;
        this.loading = false;
      },
      (error: any) => {
        console.log('Error carregant llibres', error);
        this.errorMessage = error.error?.message || 'Error carregant els llibres';
        this.loading = false;
      }
    );
  }

  filterBooks(): void {
    if (!this.searchQuery.trim()) {
      this.filteredBooks = this.books;
      return;
    }

    const query = this.searchQuery.toLowerCase();
    this.filteredBooks = this.books.filter(book =>
      book.titol.toLowerCase().includes(query) ||
      book.autor.toLowerCase().includes(query)
    );
  }

  borrowBook(bookId: string): void {
    if (this.isLoaning) return; // Evitar doble click

    this.isLoaning = true;
    this.loaningBookId = bookId;
    this.errorMessage = '';
    this.successMessage = '';

    // Data de retorn: 14 dies des d'ara
    const dataRetorn = new Date();
    dataRetorn.setDate(dataRetorn.getDate() + 14);
    const dataRetornStr = dataRetorn.toISOString();

    console.log('Enviant préstec amb:', { llibreId: bookId, dataRetornaPrevista: dataRetornStr });

    this.loanService.createLoan(bookId, dataRetornStr).subscribe({
      next: (response: any) => {
        this.isLoaning = false;
        this.loaningBookId = '';
        this.successMessage = 'Préstec solicitat correctament!';
        // Actualitzar localment sense recarregar
        const book = this.books.find(b => b._id === bookId);
        if (book && book.quantitatDisponible > 0) {
          book.quantitatDisponible -= 1;
        }
        setTimeout(() => {
          this.successMessage = '';
        }, 4000);
      },
      error: (error: any) => {
        this.isLoaning = false;
        this.loaningBookId = '';
        this.errorMessage = error.error?.message || 'Error solicitant el préstec';
        // L'error desapareix després de 4 segons
        setTimeout(() => {
          this.errorMessage = '';
        }, 4000);
      }
    });
  }

  goHome(): void {
    this.router.navigate(['/home']);
  }
}
<div class="books-container">
  <div class="header">
    <h1>Catàleg de Llibres</h1>
    <button class="btn-back" (click)="goHome()">Tornar al Home</button>
  </div>

  <div class="search-section">
    <input
      type="text"
      [(ngModel)]="searchQuery"
      placeholder="Buscar per títol o autor..."
      class="search-input"
    />
    <button class="btn-search" (click)="filterBooks()">Buscar</button>
  </div>

  <div *ngIf="loading" class="loading">
    Carregant llibres...
  </div>

  <div *ngIf="!loading && filteredBooks.length === 0" class="empty-state">
    <p>No s'han trobat llibres</p>
  </div>

  <div *ngIf="!loading && filteredBooks.length > 0" class="books-section">
    <div class="books-grid">
      <div *ngFor="let book of filteredBooks" class="book-card">
        <div class="book-cover">
          <div class="cover-placeholder">
            📚
          </div>
        </div>

        <div class="book-info">
          <h3 class="book-title">{{ book.titol }}</h3>
          <p class="book-author">{{ book.autor }}</p>
          <p class="book-category">{{ book.categoria }}</p>

          <div class="book-details">
            <div class="detail">
              <span class="label">ISBN:</span>
              <span class="value">{{ book.isbn }}</span>
            </div>
            <div class="detail">
              <span class="label">Any:</span>
              <span class="value">{{ book.any }}</span>
            </div>
            <div class="detail">
              <span class="label">Còpies Disponibles:</span>
              <span class="value" [ngClass]="book.quantitatDisponible === 0 ? 'no-available' : ''">
                {{ book.quantitatDisponible }}
              </span>
            </div>
          </div>

          <button
            class="btn-loan"
            (click)="borrowBook(book._id)"
            [disabled]="book.quantitatDisponible === 0 || loaningBookId === book._id"
          >
            <span *ngIf="loaningBookId === book._id">Solicitant...</span>
            <span *ngIf="loaningBookId !== book._id && book.quantitatDisponible === 0">No Disponible</span>
            <span *ngIf="loaningBookId !== book._id && book.quantitatDisponible > 0">Solicitar Préstec</span>
          </button>
        </div>
      </div>
    </div>
  </div>

  <div *ngIf="successMessage" class="toast success-toast">
    <span class="toast-icon">✅</span>
    <span>{{ successMessage }}</span>
  </div>

  <div *ngIf="errorMessage" class="toast error-toast">
    <span class="toast-icon">❌</span>
    <span>{{ errorMessage }}</span>
  </div>
</div>
